import assert from 'node:assert/strict'
import { execFileSync, spawn } from 'node:child_process'
import { existsSync, mkdirSync, rmSync, writeFileSync } from 'node:fs'

const BASE = process.env.QA_BASE ?? 'http://127.0.0.1:4173/catfood_web/'
const PRODUCT_SHA = process.env.PRODUCT_SHA ?? 'unknown'
const SUPABASE_URL = process.env.VITE_SUPABASE_URL
const SUPABASE_KEY = process.env.VITE_SUPABASE_PUBLISHABLE_KEY
const OUT = 'qa-artifacts'
const STORAGE_KEY = 'catfood.switch-session.v1'
const LONG_CANDIDATE = '울트라 프로틴+ 스킨 & 코트 & 다이제스티브 캣 레시피'
mkdirSync(OUT, { recursive: true })
assert.ok(SUPABASE_URL && SUPABASE_KEY, 'public Supabase config missing')
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))
const j = (value) => JSON.stringify(value)

async function apiRows(view, params = {}) {
  const url = new URL(`${SUPABASE_URL.replace(/\/$/, '')}/rest/v1/${view}`)
  for (const [key, value] of Object.entries(params)) url.searchParams.set(key, String(value))
  const response = await fetch(url, { headers: { apikey: SUPABASE_KEY, 'Accept-Profile': 'api' } })
  assert.equal(response.ok, true, `${view} read failed ${response.status}`)
  return response.json()
}

async function catalogContext() {
  const rows = await apiRows('effective_product_catalog_summary', {
    select: 'product_id,brand,canonical_name,feed_type,life_stage,variant_count,has_variants',
    order: 'brand.asc,canonical_name.asc', limit: 1000,
  })
  const current = rows.find((x) => x.brand === 'AATU' && x.canonical_name === '연어' && Number(x.variant_count) >= 2)
    ?? rows.find((x) => Number(x.variant_count) >= 2 && x.brand && x.canonical_name && x.feed_type)
  assert.ok(current, 'no multi-SKU current product')
  const variants = await apiRows('switch_current_variant_options', {
    select: 'product_id,variant_id,package_size_text,package_weight_g,display_rank',
    product_id: `eq.${current.product_id}`, order: 'display_rank.asc,variant_id.asc', limit: 100,
  })
  assert.ok(variants.length >= 2, 'current product needs multiple real variants')
  const sku = variants.find((x) => /(^|\s)1\s*kg/i.test(x.package_size_text ?? '')) ?? variants[0]
  const counts = new Map()
  for (const x of rows) if (x.brand) counts.set(x.brand, (counts.get(x.brand) ?? 0) + 1)
  const multiBrand = [...counts.entries()].sort((a,b)=>b[1]-a[1]).find(([,count])=>count >= 8)?.[0]
  assert.ok(multiBrand, 'no brand with enough search rows')
  return { rows, current, variants, sku, multiBrand }
}

class Cdp {
  constructor(url) { this.url=url; this.ws=null; this.id=1; this.pending=new Map(); this.requests=[] }
  async connect() {
    this.ws = new WebSocket(this.url)
    await new Promise((resolve,reject)=>{ const t=setTimeout(()=>reject(new Error('websocket timeout')),15000); this.ws.addEventListener('open',()=>{clearTimeout(t);resolve()}, {once:true}); this.ws.addEventListener('error',()=>reject(new Error('websocket error')), {once:true}) })
    this.ws.addEventListener('message',(event)=>{ const m=JSON.parse(event.data); if(m.method==='Network.requestWillBeSent') this.requests.push({url:m.params.request.url,method:m.params.request.method}); const p=m.id?this.pending.get(m.id):null; if(!p)return; this.pending.delete(m.id); m.error?p.reject(new Error(m.error.message)):p.resolve(m.result) })
    await this.send('Page.enable'); await this.send('Runtime.enable'); await this.send('DOM.enable'); await this.send('CSS.enable'); await this.send('Network.enable')
    await this.send('Emulation.setLocaleOverride',{locale:'ko-KR'})
    await this.send('Page.addScriptToEvaluateOnNewDocument',{source:`(()=>{const f=window.fetch.bind(window);window.__qaBlockedAnalytics=0;window.__qaBlockedWrites=0;window.fetch=(input,init={})=>{const u=typeof input==='string'?input:(input&&input.url)||'';const m=String(init.method||(input&&input.method)||'GET').toUpperCase();if(u.includes('/functions/v1/decision-intake')){window.__qaBlockedAnalytics++;return Promise.reject(new TypeError('QA blocked analytics'))}if(u.includes('gnosbstdatkytsyxuapt.supabase.co')&&!['GET','HEAD','OPTIONS'].includes(m)){window.__qaBlockedWrites++;return Promise.reject(new TypeError('QA blocked write'))}return f(input,init)}})();`})
  }
  send(method,params={}) { const id=this.id++; return new Promise((resolve,reject)=>{this.pending.set(id,{resolve,reject});this.ws.send(JSON.stringify({id,method,params}))}) }
  async eval(expression) { const r=await this.send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true}); if(r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description??r.exceptionDetails.text); return r.result?.value }
  async wait(expression,label,ms=30000) { const end=Date.now()+ms; while(Date.now()<end){ try{if(await this.eval(`Boolean(${expression})`))return}catch{} await sleep(120)} throw new Error(`timeout: ${label}`) }
  async nav(url) { await this.send('Page.navigate',{url}); await this.wait(`document.readyState==='complete'`,'ready'); await this.wait(`document.querySelector('#root')&&document.body.innerText.length>0`,'root'); await this.eval('document.fonts?.ready'); await sleep(250) }
  async shot(path) { await this.eval('document.fonts?.ready'); await sleep(100); const r=await this.send('Page.captureScreenshot',{format:'png',fromSurface:true,captureBeyondViewport:false}); writeFileSync(path,Buffer.from(r.data,'base64')) }
  async platformFonts(selector) { const {root}=await this.send('DOM.getDocument',{depth:1}); const {nodeId}=await this.send('DOM.querySelector',{nodeId:root.nodeId,selector}); assert.ok(nodeId,`font node missing ${selector}`); return (await this.send('CSS.getPlatformFontsForNode',{nodeId})).fonts??[] }
  close(){try{this.ws?.close()}catch{}}
}

async function launch(width,height,mobile=true) {
  const bin='/usr/bin/google-chrome'; assert.ok(existsSync(bin),'Chrome unavailable'); const version=execFileSync(bin,['--version'],{encoding:'utf8'}).trim()
  const port=9300+(process.pid%200)+(width%37); const dir=`/tmp/pr23-${width}-${process.pid}`; rmSync(dir,{recursive:true,force:true})
  const proc=spawn(bin,['--headless=new','--no-sandbox','--disable-dev-shm-usage','--disable-gpu','--disable-cache',`--remote-debugging-port=${port}`,`--user-data-dir=${dir}`,'about:blank'],{stdio:'ignore'})
  for(let i=0;i<200;i++){ try{const pages=await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();const page=pages.find(x=>x.type==='page'&&x.webSocketDebuggerUrl);if(page){const cdp=new Cdp(page.webSocketDebuggerUrl);await cdp.connect();await cdp.send('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile,screenWidth:width,screenHeight:height});await cdp.send('Emulation.setUserAgentOverride',{userAgent:mobile?'Mozilla/5.0 (Linux; Android 16; Mobile) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/152.0.0.0 Mobile Safari/537.36':'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/152.0.0.0 Safari/537.36',acceptLanguage:'ko-KR,ko;q=0.9,en;q=0.8',platform:mobile?'Android':'Linux'});return{cdp,proc,dir,version}}}catch{} await sleep(100)}
  throw new Error('Chrome launch timeout')
}

async function setInput(cdp,value) {
  const ok=await cdp.eval(`(()=>{const n=document.querySelector('.switch-find-search input');if(!n)return false;const s=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;s.call(n,${j(value)});n.dispatchEvent(new Event('input',{bubbles:true}));return true})()`); assert.equal(ok,true,'search input missing'); await sleep(220)
}
async function clickText(cdp,text,selector='button') { const ok=await cdp.eval(`(()=>{const n=[...document.querySelectorAll(${j(selector)})].find(x=>x.textContent.trim()===${j(text)}||x.textContent.includes(${j(text)}));if(!n)return false;n.click();return true})()`); assert.equal(ok,true,`button missing ${text}`); await sleep(180) }
async function clickSelectorContaining(cdp,selector,text) { const ok=await cdp.eval(`(()=>{const n=[...document.querySelectorAll(${j(selector)})].find(x=>x.textContent.includes(${j(text)}));if(!n)return false;n.click();return true})()`); assert.equal(ok,true,`${selector} missing ${text}`); await sleep(180) }
async function state(cdp){return cdp.eval(`(()=>{const r=sessionStorage.getItem(${j(STORAGE_KEY)});return r?JSON.parse(r).state:null})()`)}
async function capture(cdp,prefix,name,selectors=[]){const metrics=await measure(cdp,selectors);const file=`${prefix}-${name}.png`;await cdp.shot(`${OUT}/${file}`);return{file,metrics}}
async function measure(cdp,selectors=[]){return cdp.eval(`(()=>{const vw=innerWidth,vh=innerHeight;const q=(s)=>document.querySelector(s);const visible=e=>{if(!e)return false;const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>0&&r.height>0};const info=s=>{const e=q(s);if(!e)return{selector:s,missing:true};const r=e.getBoundingClientRect(),cs=getComputedStyle(e);return{selector:s,text:(e.textContent||'').trim(),rect:[Math.round(r.left),Math.round(r.top),Math.round(r.width),Math.round(r.height)],client:[e.clientWidth,e.clientHeight],scroll:[e.scrollWidth,e.scrollHeight],overflow:[cs.overflowX,cs.overflowY],maxHeight:cs.maxHeight,minHeight:cs.minHeight,display:cs.display,gridTemplateColumns:cs.gridTemplateColumns,whiteSpace:cs.whiteSpace,textOverflow:cs.textOverflow,wordBreak:cs.wordBreak,lineClamp:cs.webkitLineClamp||null}};const all=[...document.querySelectorAll('body *')].filter(visible);return{viewport:[vw,vh],windowScrollY:Math.round(scrollY),document:[document.documentElement.scrollWidth,document.documentElement.scrollHeight],horizontal:all.filter(e=>{const r=e.getBoundingClientRect();return r.left<-1||r.right>vw+1}).slice(0,12).map(e=>({tag:e.tagName,class:e.className,rect:[Math.round(e.getBoundingClientRect().left),Math.round(e.getBoundingClientRect().right)],text:(e.textContent||'').trim().slice(0,80)})),nested:all.filter(e=>{const cs=getComputedStyle(e);return e.scrollHeight>e.clientHeight+2&&['auto','scroll'].includes(cs.overflowY)&&e.clientHeight>60}).slice(0,15).map(e=>({class:e.className,client:e.clientHeight,scroll:e.scrollHeight,overflow:getComputedStyle(e).overflowY})),targets:${j(selectors)}.map(info)}})()`)}
async function reach(cdp,selector){const before=await cdp.eval(`(()=>{const e=document.querySelector(${j(selector)});if(!e)return null;const r=e.getBoundingClientRect();return{scrollY,rect:[r.left,r.top,r.width,r.height],visible:r.top>=0&&r.bottom<=innerHeight}})()`);assert.ok(before,`reach missing ${selector}`);await cdp.eval(`document.querySelector(${j(selector)}).scrollIntoView({block:'center',inline:'nearest'})`);await sleep(180);const after=await cdp.eval(`(()=>{const e=document.querySelector(${j(selector)});const r=e.getBoundingClientRect();const x=Math.max(0,Math.min(innerWidth-1,r.left+r.width/2)),y=Math.max(0,Math.min(innerHeight-1,r.top+r.height/2));const top=document.elementFromPoint(x,y);return{scrollY,rect:[r.left,r.top,r.width,r.height],visible:r.top>=0&&r.bottom<=innerHeight,centerHit:Boolean(top&&(top===e||e.contains(top)))}})()`);assert.equal(after.visible,true,`${selector} not reachable`);assert.equal(after.centerHit,true,`${selector} covered`);return{before,after}}

async function waitCatalog(cdp){await cdp.wait(`document.querySelector('.switch-find-search input')`,'switch search')}
async function searchCount(cdp,query){await setInput(cdp,query);await cdp.wait(`document.querySelector('.switch-find-results-heading span')&&document.querySelector('.switch-find-results-heading span').textContent.includes('개 표시')`,'search count');return cdp.eval(`document.querySelectorAll('.switch-find-result').length`)}
async function findUniqueQuery(cdp,rows){const options=[];for(const x of rows.slice(0,120)){options.push(`${x.brand} ${x.canonical_name}`,x.canonical_name)}for(const q of options){if(!q?.trim())continue;const n=await searchCount(cdp,q);if(n===1)return q}throw new Error('unable to find one-result query')}

async function selectCurrent(cdp,ctx){const query=`${ctx.current.brand} ${ctx.current.canonical_name}`;await setInput(cdp,query);await cdp.wait(`document.querySelectorAll('.switch-find-result').length>0`,'current result');await clickSelectorContaining(cdp,'.switch-find-result',ctx.current.canonical_name);await cdp.wait(`document.querySelector('.switch-current-preview')`,'current preview');await clickText(cdp,'이 제품을 현재 사료로 선택');await cdp.wait(`document.querySelector('.switch-sku-option')`,'sku options');await cdp.wait(`!document.body.innerText.includes('판매 규격을 불러오는 중입니다.')`,'sku load')}
async function chooseSku(cdp,ctx){const label=ctx.sku.package_size_text||'1 kg';await clickSelectorContaining(cdp,'.switch-sku-option',label);await sleep(150);const s=await state(cdp);assert.equal(s.variantSelection.kind,'variant');assert.equal(s.variantSelection.variantId,ctx.sku.variant_id);return label}
async function configureToResults(cdp){await clickText(cdp,'다음');await cdp.wait(`document.body.innerText.includes('무엇을 바꾸고 싶으신가요')||document.querySelector('.switch-no-change')`,'change step');await clickText(cdp,'다른 브랜드로 보기');await clickText(cdp,'다음');await cdp.wait(`document.body.innerText.includes('유지하고 싶은')||[...document.querySelectorAll('button')].some(x=>x.textContent.includes('유지'))`,'keep step');await clickText(cdp,'건식 유지');await clickText(cdp,'후보');await cdp.wait(`document.querySelector('.switch-results-stage')`,'results')}

async function progressAudit(cdp){return cdp.eval(`(()=>{const p=document.querySelector('.switch-progress');const items=[...p.querySelectorAll('li')];return{scroll:[p.clientWidth,p.scrollWidth],items:items.map(li=>{const num=li.querySelector(':scope>span'),label=li.querySelector('strong'),rn=num.getBoundingClientRect(),rl=label.getBoundingClientRect(),cs=getComputedStyle(label),after=getComputedStyle(label,'::after');return{text:label.textContent.trim(),after:after.content,current:li.getAttribute('aria-current'),classes:li.className,numRect:[rn.left,rn.top,rn.width,rn.height],labelRect:[rl.left,rl.top,rl.width,rl.height],numberAbove:rn.bottom<=rl.top+1,whiteSpace:cs.whiteSpace,textOverflow:cs.textOverflow,fontSize:cs.fontSize}})}})()`)}

async function mobileSearchEvidence(cdp,prefix,ctx,result){
  await setInput(cdp,'__qa_no_match_9f31c__');await cdp.wait(`document.querySelectorAll('.switch-find-result').length===0&&document.body.innerText.includes('검색 결과가 없습니다.')`,'zero results');result.zero=await capture(cdp,prefix,'01-zero-results',['.switch-find-body','.switch-find-results-list']);assert.ok(result.zero.metrics.targets[0].rect[3]<320,'zero-result body retained large min height')
  const unique=await findUniqueQuery(cdp,ctx.rows);result.uniqueQuery=unique;result.oneCount=await searchCount(cdp,unique);assert.equal(result.oneCount,1);result.one=await capture(cdp,prefix,'02-one-result',['.switch-find-body','.switch-find-results-list']);assert.ok(result.one.metrics.targets[0].rect[3]<330,'one-result body retained large min height')
  const many=await searchCount(cdp,ctx.multiBrand);assert.ok(many>=2,'many-result query too small');const list=await cdp.eval(`(()=>{const e=document.querySelector('.switch-find-results-list'),s=getComputedStyle(e);return{count:e.children.length,clientHeight:e.clientHeight,scrollHeight:e.scrollHeight,overflowY:s.overflowY,maxHeight:s.maxHeight}})()`);result.searchList=list;assert.equal(list.overflowY,'visible');assert.equal(list.maxHeight,'none');assert.ok(list.scrollHeight<=list.clientHeight+1,'mobile results list is still an internal scroller')
  const lastIndex=many-1;const lastSelector=`.switch-find-result:nth-child(${lastIndex+1})`;result.lastReach=await reach(cdp,lastSelector);result.lastBefore=await capture(cdp,prefix,'03-last-result-reached',[lastSelector,'.switch-find-results-list']);const beforeY=await cdp.eval('scrollY');const lastName=await cdp.eval(`document.querySelector(${j(lastSelector)}).querySelector('.switch-find-result-copy strong').textContent.trim()`);result.lastName=lastName;await cdp.eval(`document.querySelector(${j(lastSelector)}).click()`);await cdp.wait(`document.querySelector('.switch-current-preview')`,'last preview');result.preview=await capture(cdp,prefix,'04-last-result-preview',['.switch-current-preview']);await clickText(cdp,'닫기 ×');await cdp.wait(`!document.querySelector('.switch-current-preview')`,'preview close');const selected=await cdp.eval(`(()=>{const e=[...document.querySelectorAll('.switch-find-result')].find(x=>x.classList.contains('is-selected'));if(!e)return null;const r=e.getBoundingClientRect();return{text:e.textContent.trim(),scrollY,visible:r.bottom>0&&r.top<innerHeight,rect:[r.left,r.top,r.width,r.height]}})()`);assert.ok(selected&&selected.text.includes(lastName),'selected last row not restored');if(!selected.visible){await cdp.eval(`document.querySelector('.switch-find-result.is-selected').scrollIntoView({block:'center'})`);await sleep(120)}result.returnState={beforeY,afterY:await cdp.eval('scrollY'),selected:await cdp.eval(`(()=>{const e=document.querySelector('.switch-find-result.is-selected'),r=e.getBoundingClientRect();return{text:e.textContent.trim(),visible:r.bottom>0&&r.top<innerHeight,rect:[r.left,r.top,r.width,r.height]}})()`)};assert.equal(result.returnState.selected.visible,true,'selected result not reachable after preview close');result.returnCapture=await capture(cdp,prefix,'05-preview-return',['.switch-find-result.is-selected'])
}

async function mobileFlow(width,height,ctx,browserVersion){
  const prefix=`pr23-${PRODUCT_SHA.slice(0,8)}-${width}x${height}`;const {cdp,proc,dir}=await launch(width,height,true);const r={viewport:[width,height],browserVersion,path:[],captures:[],search:{},progress:null,candidate:null,stateRoundtrip:null,network:null,font:null}
  const cap=async(name,selectors=[])=>{const x=await capture(cdp,prefix,name,selectors);r.captures.push(x);return x}
  try{
    await cdp.nav(`${BASE}?view=workspace&mode=switch`);await waitCatalog(cdp);await mobileSearchEvidence(cdp,prefix,ctx,r.search)
    await selectCurrent(cdp,ctx);const skuLabel=await chooseSku(cdp,ctx);r.sku={label:skuLabel,id:ctx.sku.variant_id};r.progress=await progressAudit(cdp);assert.equal(r.progress.scroll[0],r.progress.scroll[1],'mobile progress horizontally scrolls');assert.deepEqual(r.progress.items.map(x=>x.text),['현재 제품','사용 규격','바꿀 것','유지할 것','후보']);assert.equal(r.progress.items.filter(x=>x.current==='step').length,1);assert.ok(r.progress.items.every(x=>x.numberAbove),'progress number is not above label');await cap('06-sku-progress',['.switch-progress','.switch-sku-option.is-selected'])
    await configureToResults(cdp);await cap('07-results',['.switch-session-bar','.switch-candidate-list']);
    const longExists=await cdp.eval(`[...document.querySelectorAll('.switch-candidate-row')].some(x=>x.textContent.includes(${j(LONG_CANDIDATE)}))`);assert.equal(longExists,true,`long candidate not visible in current candidate window`);await clickSelectorContaining(cdp,'.switch-candidate-row',LONG_CANDIDATE);await cdp.wait(`document.querySelector('.switch-candidate-inspector')`,'candidate inspector');const identity=await cdp.eval(`(()=>{const box=document.querySelector('.switch-inspector-identity'),img=box.querySelector('.switch-inspector-image,.switch-image-placeholder'),h=box.querySelector('h1'),rb=box.getBoundingClientRect(),ri=img.getBoundingClientRect(),rh=h.getBoundingClientRect(),cs=getComputedStyle(h);return{name:h.textContent.trim(),box:[rb.left,rb.top,rb.width,rb.height],image:[ri.left,ri.top,ri.width,ri.height],title:[rh.left,rh.top,rh.width,rh.height],titleBelowImage:rh.top>=ri.bottom-1,titleWidthRatio:rh.width/rb.width,whiteSpace:cs.whiteSpace,textOverflow:cs.textOverflow,lineClamp:cs.webkitLineClamp||null,scroll:[h.clientWidth,h.scrollWidth],imageFit:getComputedStyle(img).objectFit}})()`);assert.equal(identity.name,LONG_CANDIDATE);assert.equal(identity.titleBelowImage,true);assert.ok(identity.titleWidthRatio>.85,'candidate title does not use full mobile width');assert.equal(identity.textOverflow,'clip');assert.ok(!identity.lineClamp||identity.lineClamp==='none','candidate title line-clamped');assert.ok(identity.scroll[1]<=identity.scroll[0]+1,'candidate title horizontally clipped');r.candidate=identity;r.detailReach=await reach(cdp,'.switch-candidate-inspector .switch-primary-action');await cap('08-long-candidate-inspector',['.switch-inspector-identity','.switch-candidate-inspector .switch-primary-action']);
    await clickText(cdp,'닫기 ×');await cdp.wait(`!document.querySelector('.switch-candidate-inspector')`,'inspector close');await clickText(cdp,'조건 수정');await cdp.wait(`document.querySelector('.switch-step-layout')`,'change edit');const before=await state(cdp);await clickText(cdp,'← 사용 규격');await cdp.wait(`document.querySelector('.switch-sku-list')`,'explicit sku back');const afterSku=await state(cdp);assert.equal(afterSku.variantSelection.variantId,ctx.sku.variant_id);assert.equal(afterSku.changeBrand,true);assert.equal(afterSku.keep.feedType,'건식');assert.ok(await cdp.eval(`Boolean(document.querySelector('.switch-sku-option.is-selected'))`));await cap('09-explicit-back-sku',['.switch-progress','.switch-sku-option.is-selected']);await clickText(cdp,'다음');await cdp.wait(`document.querySelector('.switch-no-change')`,'change reentry');const afterChange=await state(cdp);assert.equal(afterChange.variantSelection.variantId,ctx.sku.variant_id);assert.equal(afterChange.changeBrand,true);assert.equal(afterChange.keep.feedType,'건식');r.stateRoundtrip={before,afterSku,afterChange};await cap('10-change-reentry',['.switch-progress','.switch-choice.is-active']);
    const fonts=await cdp.platformFonts('.switch-progress li[aria-current="step"] strong');r.font=fonts;assert.ok(fonts.some(x=>x.familyName.includes('Noto Sans CJK KR')),`Korean font mismatch ${JSON.stringify(fonts)}`)
    const blocked=await cdp.eval(`({analytics:window.__qaBlockedAnalytics||0,writes:window.__qaBlockedWrites||0})`);const sentAnalytics=cdp.requests.filter(x=>x.url.includes('/functions/v1/decision-intake'));const sentWrites=cdp.requests.filter(x=>x.url.includes('gnosbstdatkytsyxuapt.supabase.co')&&!['GET','HEAD','OPTIONS'].includes(x.method));assert.equal(sentAnalytics.length,0);assert.equal(sentWrites.length,0);r.network={blocked,sentAnalytics,sentWrites,publicReads:cdp.requests.filter(x=>x.url.includes('gnosbstdatkytsyxuapt.supabase.co')&&x.method==='GET').length}
    return r
  } finally {cdp.close();proc.kill('SIGTERM');await sleep(100);try{rmSync(dir,{recursive:true,force:true})}catch{}}
}

async function boundary(width,height,ctx){const prefix=`pr23-${PRODUCT_SHA.slice(0,8)}-${width}x${height}`;const {cdp,proc,dir,version}=await launch(width,height,width<=761);const r={viewport:[width,height],version,captures:[]};try{await cdp.nav(`${BASE}?view=workspace&mode=switch`);await waitCatalog(cdp);await searchCount(cdp,ctx.multiBrand);r.search=await cdp.eval(`(()=>{const e=document.querySelector('.switch-find-results-list'),s=getComputedStyle(e);return{count:e.querySelectorAll('.switch-find-result').length,overflowY:s.overflowY,maxHeight:s.maxHeight,clientHeight:e.clientHeight,scrollHeight:e.scrollHeight}})()`);if(width<=760){assert.equal(r.search.overflowY,'visible');assert.equal(r.search.maxHeight,'none')}else{assert.equal(r.search.overflowY,'auto');assert.notEqual(r.search.maxHeight,'none');assert.ok(r.search.scrollHeight>=r.search.clientHeight)}r.captures.push(await capture(cdp,prefix,'boundary-search',['.switch-find-results-list']));await selectCurrent(cdp,ctx);await chooseSku(cdp,ctx);r.progress=await progressAudit(cdp);if(width<=760){assert.ok(r.progress.items.every(x=>x.numberAbove));assert.equal(r.progress.scroll[0],r.progress.scroll[1])}else{assert.ok(r.progress.items.some(x=>!x.numberAbove),'761/desktop unexpectedly uses mobile progress stacking')}r.captures.push(await capture(cdp,prefix,'boundary-progress',['.switch-progress']));return r}finally{cdp.close();proc.kill('SIGTERM');await sleep(80);try{rmSync(dir,{recursive:true,force:true})}catch{}}}

const ctx=await catalogContext();const browserVersion=execFileSync('/usr/bin/google-chrome',['--version'],{encoding:'utf8'}).trim();const report={productSha:PRODUCT_SHA,status:'running',browserVersion,koreanFont:execFileSync('fc-match',[':lang=ko'],{encoding:'utf8'}).trim(),context:{current:ctx.current,sku:ctx.sku,multiBrand:ctx.multiBrand,longCandidate:LONG_CANDIDATE},expected:{mobileSteps:'number above full label; no horizontal progress scroll',mobileSearch:'document scroll only; zero/one content-sized',mobileCandidate:'image then full-width full name',boundary:'760 mobile behavior; 761 and 1280 retain non-mobile internal search scroll'},mobile:[],boundary:[],error:null}
try{report.mobile.push(await mobileFlow(360,844,ctx,browserVersion));report.mobile.push(await mobileFlow(390,900,ctx,browserVersion));report.boundary.push(await boundary(760,900,ctx));report.boundary.push(await boundary(761,900,ctx));report.boundary.push(await boundary(1280,900,ctx));report.status='pass'}catch(error){report.status='fail';report.error=String(error?.stack||error);throw error}finally{writeFileSync(`${OUT}/report.json`,JSON.stringify(report,null,2))}
console.log('PR23_MOBILE_SWITCH_DESIGN_QA_PASS',JSON.stringify({productSha:PRODUCT_SHA,browserVersion,current:[ctx.current.brand,ctx.current.canonical_name],sku:ctx.sku.package_size_text,mobile:report.mobile.map(x=>({viewport:x.viewport,search:x.search.searchList,progress:x.progress.items.map(i=>({text:i.text,current:i.current,numberAbove:i.numberAbove})),candidate:x.candidate?.name,writes:x.network?.sentWrites?.length,analytics:x.network?.sentAnalytics?.length})),boundary:report.boundary.map(x=>({viewport:x.viewport,search:x.search,progress:x.progress.items.map(i=>({text:i.text,numberAbove:i.numberAbove}))}))}))
